// Loader of the guides of the public application (depositor, recipient), generated by
// scripts/build-help.mjs. Kept apart from adminGuides.ts so that the public bundle does not even
// reference the admin guides.
import { createHelpLoader } from './load';
import type { HelpGuideSet } from './types';

const loader = createHelpLoader(import.meta.glob<{ default: HelpGuideSet }>('./generated/*-public.ts'));

/** Loads the public guides in a language (English when the language has none). */
export function loadPublicGuides(lang: string): Promise<HelpGuideSet> {
  return loader('public', lang);
}
